class Solution {
public:
    bool wordPatternMatch(string pattern, string s) {
        unordered_map<char, string> p2w;
        unordered_map<string, char> w2p;
        return backtrack(pattern, 0, s, 0, p2w, w2p);
    }

private:
    bool backtrack(const string& p, size_t pIdx, const string& s, size_t sIdx,
                   unordered_map<char, string>& p2w, unordered_map<string, char>& w2p) {
        if (pIdx == p.size() && sIdx == s.size()) return true;
        if (pIdx == p.size() || sIdx == s.size()) return false;
        char ch = p[pIdx];
        if (p2w.count(ch)) {
            const string& w = p2w[ch];
            if (s.compare(sIdx, w.size(), w) != 0) return false;
            return backtrack(p, pIdx + 1, s, sIdx + w.size(), p2w, w2p);
        }
        for (size_t k = sIdx + 1; k <= s.size(); ++k) {
            string sub = s.substr(sIdx, k - sIdx);
            if (w2p.count(sub)) continue;
            p2w[ch] = sub;
            w2p[sub] = ch;
            if (backtrack(p, pIdx + 1, s, k, p2w, w2p)) return true;
            p2w.erase(ch);
            w2p.erase(sub);
        }
        return false;
    }
};

class Solution {
    public boolean wordPatternMatch(String pattern, String s) {
        Map<Character, String> p2w = new HashMap<>();
        Map<String, Character> w2p = new HashMap<>();
        return backtrack(pattern, 0, s, 0, p2w, w2p);
    }

    private boolean backtrack(String p, int pIdx, String s, int sIdx,
                              Map<Character, String> p2w, Map<String, Character> w2p) {
        if (pIdx == p.length() && sIdx == s.length()) return true;
        if (pIdx == p.length() || sIdx == s.length()) return false;
        char ch = p.charAt(pIdx);
        if (p2w.containsKey(ch)) {
            String w = p2w.get(ch);
            if (!s.startsWith(w, sIdx)) return false;
            return backtrack(p, pIdx + 1, s, sIdx + w.length(), p2w, w2p);
        }
        for (int k = sIdx + 1; k <= s.length(); k++) {
            String sub = s.substring(sIdx, k);
            if (w2p.containsKey(sub)) continue;
            p2w.put(ch, sub);
            w2p.put(sub, ch);
            if (backtrack(p, pIdx + 1, s, k, p2w, w2p)) return true;
            p2w.remove(ch);
            w2p.remove(sub);
        }
        return false;
    }
}

/**
 * @param {string} pattern
 * @param {string} s
 * @return {boolean}
 */
var wordPatternMatch = function(pattern, s) {
    const p2w = new Map();
    const w2p = new Map();
    function backtrack(pIdx, sIdx) {
        if (pIdx === pattern.length && sIdx === s.length) return true;
        if (pIdx === pattern.length || sIdx === s.length) return false;
        const ch = pattern[pIdx];
        if (p2w.has(ch)) {
            const w = p2w.get(ch);
            if (!s.startsWith(w, sIdx)) return false;
            return backtrack(pIdx + 1, sIdx + w.length);
        }
        for (let k = sIdx + 1; k <= s.length; k++) {
            const sub = s.slice(sIdx, k);
            if (w2p.has(sub)) continue;
            p2w.set(ch, sub);
            w2p.set(sub, ch);
            if (backtrack(pIdx + 1, k)) return true;
            p2w.delete(ch);
            w2p.delete(sub);
        }
        return false;
    }
    return backtrack(0, 0);
};
